INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('topic:KURS-014','topic','','Sekcja zasilania VRM','','description: VRM (mosfety i dławiki) dostarcza prąd do CPU. Przegrzanie sekcji zasilania powoduje throttling i restarty, zwłaszcza przy mocnym procesorze lub OC. symptoms: • Restarty przy pełnym obciążeniu CPU • Throttling mimo niskich temperatur rdzenia CPU • Bardzo gorące radiatory obok gniazda procesora • Brak stabilności przy overclockingu / dużym poborze mocy diagnosis: • Zmierz temperaturę VRM (HWiNFO — ''VRM MOS''). • Sprawdź czy sekcja zasilania ma radiator i czy dobrze przylega. • Oceń airflow nad gniazdem CPU (brak nadmuchu na VRM). • Obserwuj napięcie Vcore i pobór mocy pod obciążeniem. repair: • Dołóż aktywny wentylator nadmuchujący na sekcję VRM. • Wymień pady termiczne pod radiatorem VRM. • Ogranicz PPT / pobór mocy CPU w BIOS. • Do topowego CPU dobierz płytę z mocniejszym VRM. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-015','topic','','Stuttering / mikroprzycięcia','','description: Krótkie zacięcia mimo wysokiej średniej liczby klatek. Najczęstsze przyczyny: sterowniki, RAM bez XMP, throttling, wolny dysk i procesy w tle. symptoms: • Krótkie zacięcia co kilka sekund • Niskie 1% low mimo wysokiego średniego FPS • Płynność ''szarpie'' przy stałym FPS • Dźwięk trzeszczy w momencie zacięcia diagnosis: • Włącz licznik frametime / 1% low (MSI Afterburner, CapFrameX). • Sprawdź czy RAM ma włączony XMP/EXPO i pracuje w dual channel. • Monitoruj temperatury pod kątem throttlingu. • Sprawdź obciążenie dysku (100%) i procesy w tle. repair: • Włącz XMP/EXPO oraz dual channel (kości w slotach A2/B2). • Zrób czystą instalację sterowników GPU (DDU). • Włącz Resizable BAR, wyłącz nakładki (Game Bar/overlay). • Przenieś grę na SSD. • Ogranicz FPS do częstotliwości monitora (limiter/V-Sync). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-016','topic','','Porty USB','','description: Gniazda USB i kontroler. Objawy to niewykrywane urządzenia, losowe rozłączenia i wyrobione, luźne porty. symptoms: • Urządzenie niewykrywane / ''Nieznane urządzenie USB'' • Port rozłącza się losowo (charakterystyczny dźwięk) • Gniazdo fizycznie luźne lub wyrobione • Komunikat ''USB przekroczyło limit mocy'' diagnosis: • Przetestuj to samo urządzenie w innym porcie. • Sprawdź kontroler USB w Menedżerze urządzeń (wykrzykniki). • Uruchom system live z pendrive, aby wykluczyć Windows. • Obejrzyj gniazdo pod kątem wygięcia styków i zabrudzenia. repair: • Wyczyść gniazdo sprężonym powietrzem i IPA. • Wyłącz ''oszczędzanie energii'' kontrolera USB (Menedżer urządzeń). • Zaktualizuj sterowniki chipsetu / USB. • Przelutuj lub wymień wyrobione gniazdo (serwis). • Użyj huba USB z własnym zasilaniem. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-017','topic','','Klawiatura / touchpad','','description: Klawiatura laptopa i touchpad. Objawy: martwe lub dublujące klawisze, brak reakcji lub ''skaczący'' kursor touchpada. symptoms: • Pojedyncze klawisze nie działają lub dublują znaki • Touchpad nie reaguje lub kursor ''skacze'' • Klawiatura działa częściowo (np. po zalaniu) • Gesty touchpada (przewijanie) nie działają diagnosis: • Przetestuj klawisze w teście online (keyboard tester). • Sprawdź czy Fn nie wyłączył touchpada. • Podłącz zewnętrzną klawiaturę/mysz USB (izoluje sprzęt od systemu). • Sprawdź sterowniki touchpada (Synaptics / Precision). repair: • Włącz touchpad (Fn + odpowiedni klawisz F lub w ustawieniach). • Zaktualizuj / przeinstaluj sterowniki touchpada. • Wyczyść zabrudzenia pod klawiszami. • Po zalaniu: odłącz zasilanie i baterię, dokładnie wysusz. • Wymień taśmę lub moduł klawiatury / touchpada. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-018','topic','','Układy scalone / reballing (BGA)','','description: Uszkodzone lutowanie kulkowe (BGA) układów GPU/chipsetu — częste po przegrzaniu. Naprawa to reballing (ponowne kulkowanie) lub wymiana układu. symptoms: • Brak obrazu mimo pracujących wentylatorów • Artefakty na ekranie • Restart / zawieszenie przy obciążeniu • Sprzęt znika z systemu po nagrzaniu diagnosis: • Test podgrzaniem — chwilowa poprawa wskazuje na zimne luty BGA. • Pomiar zwarć na liniach zasilania (multimetr). • Kontrola pod mikroskopem / kamerą termowizyjną. • Sprawdzenie układu w innym slocie / komputerze. repair: • Profesjonalny reballing stacją BGA (preheater + hot air, topnik, kulki 0.5 mm). • Wymiana układu na sprawny z użyciem szablonu (stencil). • Kontrola temperatur i test stabilności po naprawie. • W razie braku sprzętu — zleć naprawę serwisowi (linki niżej). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-019','topic','','Gniazdo ładowania / DC-IN','','description: Gniazdo zasilania (DC-IN lub USB-C) laptopa. Po zużyciu nie ładuje lub ładuje dopiero po poruszeniu wtyczki. symptoms: • Ładuje tylko pod kątem / po poruszeniu kabla • „Podłączono, nie ładuje” • Luźne, wyrobione gniazdo • Iskrzenie lub zapach spalenizny diagnosis: • Sprawdź inną ładowarkę i kabel. • Zmierz napięcie na gnieździe (multimetr). • Oględziny pod kątem złamanych pinów i pękniętego lutu. • Sprawdź obwód ładowania na płycie (kontroler). repair: • Przelutuj gniazdo DC-IN lub wymień moduł / taśmę. • Oczyść port USB-C ze sprężonym powietrzem. • Wymień uszkodzony kabel / ładowarkę. • Napraw ścieżki zasilania (serwis). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-020','topic','','Pamięć VRAM i elementy GPU','','description: Uszkodzone kości pamięci VRAM lub sekcja zasilania karty graficznej — objawiają się artefaktami lub brakiem obrazu. symptoms: • Artefakty / kolorowe piksele • Zawieszenia i błędy w grach • Brak obrazu • Błąd sterownika (kod 43) diagnosis: • Test karty w innym komputerze. • GPU-Z — odczyt typu i ilości VRAM. • Test artefaktów (FurMark / MATS). • Pomiar sekcji zasilania (VRM) karty, kontrola cewek i kondensatorów. repair: • Wymiana uszkodzonej kości VRAM (BGA — serwis). • Wymiana pasty i padów termicznych (przegrzewanie VRAM). • Naprawa sekcji zasilania (mosfety / cewki). • Reballing rdzenia GPU. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-021','topic','','Jak zdiagnozować uszkodzoną kartę graficzną','','description: Krok po kroku jak ustalić, czy problem leży w karcie graficznej i co dokładnie jej dolega. symptoms: • Brak obrazu • Artefakty • Kod 43 w Menedżerze urządzeń • Wentylatory 100% • Spadki FPS / restarty diagnosis: • Sprawdź kartę w innym PC oraz inną kartę w swoim. • Test na grafice zintegrowanej (bez GPU). • GPU-Z + czysta reinstalacja sterowników (DDU). • Obserwuj temperatury (throttling / przegrzanie VRM). • Nasłuchaj cewek (coil whine), test FurMark pod kątem artefaktów. repair: • Przełóż kartę do innego slotu PCIe. • Czysta reinstalacja sterowników (DDU). • Wymiana pasty i padów termicznych. • Sprawdź zasilanie (kable PCIe / PSU). • Serwis (reball / VRAM), jeśli usterka sprzętowa. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-022','topic','','Jak zdiagnozować uszkodzoną płytę główną','','description: Metodyczne wykrywanie usterki płyty głównej — od zasilania po kody POST. symptoms: • Brak startu (brak POST) • Kody diagnostyczne / piszczki BIOS • Brak obrazu • Losowe restarty • Nie trzyma ustawień (bateria CMOS) • Porty nie działają diagnosis: • Minimalna konfiguracja: CPU + 1 kość RAM + zasilanie. • Odczyt kodów POST (Q-Code / diody EZ Debug). • Pomiar napięć zasilacza i sekcji VRM. • Wymiana baterii CMOS + reset ustawień. • Oględziny kondensatorów, gniazd i ścieżek. repair: • Reset BIOS (zworka CLR_CMOS lub wyjęcie baterii). • Wymiana baterii CMOS (CR2032). • Przelutowanie gniazd / ścieżek (serwis). • Aktualizacja lub odtworzenie BIOS. • Wymiana płyty przy uszkodzeniu krytycznym. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-023','topic','','Reset i hasło BIOS / UEFI','','description: Jak zresetować ustawienia BIOS i poradzić sobie z zablokowanym hasłem BIOS (linki do narzędzi w sekcji zasobów niżej). symptoms: • BIOS żąda hasła przy starcie • Brak dostępu do ustawień BIOS • Komputer nie startuje po zmianach w BIOS • Komunikat „System Disabled” / „BIOS locked” diagnosis: • Ustal typ blokady (hasło supervisor / user / dysku HDD). • Zanotuj kod z ekranu (część laptopów generuje kod do master password). • Sprawdź model płyty / laptopa i wersję BIOS. repair: • PC: reset zworką CLR_CMOS lub wyjęciem baterii CMOS na kilka minut. • Starsze laptopy: generator master password (bios-pw.org) — link niżej. • Aktualizacja / flash BIOS do najnowszej wersji. • Nowsze laptopy: programator kości EEPROM (serwis). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-024','topic','','Wymiana matrycy laptopa','','description: Wymiana uszkodzonego wyświetlacza LCD/LED w laptopie (pęknięcia, plamy, brak podświetlenia). symptoms: • Pęknięty ekran / plamy atramentowe • Pasy, artefakty lub brak obrazu przy działającym HDMI • Migotanie lub ciemny ekran diagnosis: • Podłącz monitor zewnętrzny — jeśli obraz OK, wina matrycy/taśmy • Sprawdź model matrycy (naklejka z tyłu panelu) • Zweryfikuj rozdzielczość, złącze (30/40 pin eDP) i mocowania repair: • Odłącz zasilanie i baterię • Zdejmij ramkę/bezel (plastikowe zatrzaski, śruby pod gumkami) • Odkręć matrycę, połóż na klawiaturze • Odklej taśmę i odłącz złącze eDP • Zamontuj nową matrycę, podłącz taśmę, złóż ramkę • Sprawdź obraz przed pełnym złożeniem source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-025','topic','','Wymiana zawiasów / naprawa obudowy','','description: Naprawa luźnych lub wyłamanych zawiasów oraz pękniętych mocowań obudowy laptopa. symptoms: • Klapa nie trzyma kąta / trzeszczy • Pęknięta obudowa przy zawiasie • Odklejająca się ramka ekranu diagnosis: • Oceń, czy uszkodzony jest zawias, czy mocowanie w obudowie • Sprawdź dostępność zawiasów na dany model repair: • Rozłóż sekcję ekranu i palmrest • Wymień zawiasy na nowe • Wzmocnij pęknięte mocowania klejem epoksydowym / wkładkami mosiężnymi • Skręć i sprawdź płynność ruchu source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-026','topic','','Odzyskiwanie danych','','description: Odzysk plików z uszkodzonych logicznie lub fizycznie dysków HDD/SSD. symptoms: • Dysk nie wykrywany / klika • Utracone partycje lub sformatowany dysk • Błędy SMART, sektory zbojowane diagnosis: • NIE zapisuj nic na dysku źródłowym • Sprawdź SMART (CrystalDiskInfo) • Uszkodzenie logiczne vs fizyczne (dźwięki, wykrywalność) repair: • Wykonaj obraz dysku (ddrescue) na sprawny nośnik • Odzyskuj z KOPII, nie z oryginału • Logiczne: PhotoRec/R-Studio/TestDisk • Fizyczne: przekaż do laboratorium (clean room) source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-027','topic','','Instalacja / reinstalacja Windows','','description: Czysta instalacja Windows 10/11 z pendrive wraz ze sterownikami. symptoms: • System nie startuje / bardzo wolny • Pętla naprawy automatycznej • Zawirusowany system diagnosis: • Zabezpiecz dane (kopia) • Sprawdź wymagania Win11 (TPM 2.0, Secure Boot) repair: • Utwórz nośnik (Media Creation Tool) • Boot z USB, usuń stare partycje, instaluj na SSD • Zainstaluj sterowniki (chipset, GPU, sieć) • Aktualizacje + aktywacja + przywrócenie danych source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-028','topic','','Usuwanie wirusów i malware','','description: Wykrywanie i usuwanie złośliwego oprogramowania, adware i ransomware bez utraty danych. symptoms: • Reklamy, przekierowania, spowolnienie • Nieznane procesy, wysokie zużycie CPU • Zaszyfrowane pliki (ransomware) diagnosis: • Tryb awaryjny z siecią • Skan: Malwarebytes + Microsoft Defender Offline • Sprawdź autostart (Autoruns) repair: • Usuń wykryte zagrożenia, wyczyść autostart • Zresetuj przeglądarki • Zmień hasła po dezynfekcji • Ransomware: NIE płać — sprawdź nomoreransom.org source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-029','topic','','Wymiana wentylatora / czyszczenie','','description: Wymiana głośnego/niedziałającego wentylatora oraz czyszczenie układu chłodzenia i wymiana pasty. symptoms: • Głośna praca / klekotanie • Wentylator nie kręci się • Wysokie temperatury, throttling diagnosis: • Sprawdź obroty (HWiNFO) • Oceń zapchanie radiatora kurzem repair: • Rozłóż spód, odłącz wtyczkę wentylatora • Wyczyść radiator i łopatki (sprężone powietrze) • Wymień wentylator, nałóż nową pastę na CPU/GPU • Złóż i sprawdź temperatury pod obciążeniem source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-030','topic','','Wymiana baterii CMOS','','description: Wymiana baterii podtrzymującej ustawienia BIOS (CR2032). symptoms: • Zegar/data resetują się • Komunikat CMOS checksum error • Utrata ustawień BIOS po odłączeniu prądu diagnosis: • Zmierz napięcie baterii (>3V OK) • Sprawdź model (zwykle CR2032) repair: • Odłącz zasilanie • Wyjmij starą baterię z gniazda • Włóż nową CR2032 (+ do góry) • Ustaw datę/godzinę w BIOS source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-031','topic','','Naprawa podświetlenia ekranu','','description: Diagnoza ciemnego ekranu — inwerter/LED, taśma eDP lub sekcja podświetlenia na płycie. symptoms: • Ekran ciemny, obraz widoczny pod latarką • Migotanie jasności • Brak podświetlenia po zamknięciu klapy diagnosis: • Latarka: jeśli widać obraz — wina podświetlenia • Sprawdź czujnik zamknięcia klapy (magnetyczny) • Zmierz zasilanie LED na złączu repair: • Wymień taśmę eDP • Wymień matrycę (zintegrowane LED) lub pasek LED • Napraw sekcję zasilania podświetlenia na płycie (bezpiecznik/cewka) source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-032','topic','','Aktualizacja BIOS/UEFI','','description: Bezpieczna aktualizacja firmware płyty głównej/laptopa (obsługa nowych CPU, poprawki stabilności). symptoms: • Brak obsługi nowego procesora • Błędy stabilności naprawiane w nowym BIOS • Problemy z RAM/XMP diagnosis: • Ustal producenta i model + wersję BIOS • Pobierz plik TYLKO ze strony producenta repair: • Podłącz zasilanie (laptop: bateria + ładowarka) • Użyj narzędzia producenta lub EZ Flash / M-Flash • NIE wyłączaj podczas aktualizacji • Po aktualizacji załaduj domyślne, ustaw XMP/boot source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-033','topic','','Montaż i klonowanie SSD/NVMe','','description: Rozbudowa o dysk SSD/NVMe i migracja systemu bez reinstalacji. symptoms: • System wolno się uruchamia (HDD) • Brak miejsca na dane • Chęć przyspieszenia laptopa diagnosis: • Sprawdź złącze (SATA / M.2 SATA / M.2 NVMe) • Zweryfikuj wsparcie płyty i długość M.2 (2242/2260/2280) repair: • Zamontuj SSD w slocie/kieszeni • Sklonuj system (Macrium Reflect) • Ustaw nowy dysk jako startowy w BIOS • Zainicjuj stary dysk jako magazyn danych source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-034','topic','','Wymiana pasty termoprzewodzącej','','description: Wymiana wyschniętej pasty na CPU/GPU oraz opcjonalny ciekły metal — obniża temperatury o kilkanaście °C. symptoms: • Wysokie temperatury i throttling • Głośne wentylatory bez obciążenia • Nagłe wyłączenia pod obciążeniem diagnosis: • Zmierz temperatury (HWiNFO) w spoczynku i pod obciążeniem. • Sprawdź wiek laptopa/PC — pasta wysycha po 2–3 latach. • Oceń docisk chłodzenia i stan padów termicznych. repair: • Rozłóż chłodzenie, usuń starą pastę (IPA 99%). • Nałóż cienką warstwę nowej pasty (ziarno ryżu / rozsmarowanie). • Ciekły metal TYLKO na miedzi/niklu — zabezpiecz okolice lakierem. • Skręć chłodzenie równomiernie na krzyż, sprawdź temperatury. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-035','topic','','Zalanie laptopa — czyszczenie','','description: Ratunek po zalaniu wodą, kawą czy sokiem — szybkie działanie decyduje o ocaleniu płyty. symptoms: • Laptop nie włącza się po zalaniu • Korozja / lepkie ślady na płycie • Klawisze nie działają, dziwny zapach diagnosis: • NATYCHMIAST odłącz zasilanie i wyjmij baterię. • Oceń zasięg zalania i rodzaj cieczy (słodka/słona = gorzej). • Sprawdź płytę pod mikroskopem/lupą pod kątem korozji. repair: • Rozłóż laptop, wyjmij wszystkie moduły. • Umyj płytę alkoholem izopropylowym (IPA 99%) i szczoteczką. • Usuń korozję, wysusz (bez włączania min. 48 h). • Wymień skorodowane elementy, dopiero potem test zasilania. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-036','topic','','Wymiana klawiatury laptopa','','description: Wymiana uszkodzonej lub zalanej klawiatury laptopa (całości lub pojedynczych keycapów). symptoms: • Nie działają niektóre klawisze • Klawisze zacinają się / wypadają • Klawiatura po zalaniu diagnosis: • Test klawiszy online (keyboard tester). • Ustal, czy klawiatura jest osobna, czy z palmrestem. • Znajdź numer części (P/N) na taśmie klawiatury. repair: • Odłącz zasilanie i baterię. • Zwolnij zatrzaski / odkręć śruby mocujące klawiaturę. • Odłącz taśmę ZIF (podnieś zaczep, nie ciągnij). • Podłącz nową klawiaturę, zatrzaśnij, przetestuj każdy klawisz. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-037','topic','','Wymiana touchpada / gładzika','','description: Naprawa lub wymiana niedziałającego gładzika oraz jego przycisków. symptoms: • Kursor nie reaguje / skacze • Nie działają kliknięcia touchpada • Touchpad odkleja się od obudowy diagnosis: • Sprawdź, czy touchpad nie jest wyłączony (Fn / sterownik). • Zweryfikuj taśmę FFC touchpada. • Test w innym systemie / Live USB. repair: • Rozłóż palmrest / spód. • Odłącz taśmę touchpada od płyty. • Odklej i wymień moduł touchpada. • Podłącz taśmę, skalibruj w ustawieniach. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-038','topic','','Wymiana kamerki (webcam)','','description: Naprawa niedziałającej kamerki internetowej wbudowanej w ramkę ekranu. symptoms: • Kamera nie wykrywana w systemie • Czarny obraz / zniekształcenia • Dioda kamery nie świeci diagnosis: • Sprawdź sterownik i uprawnienia kamery w Windows. • Test w aparacie / Teams / Zoom. • Zweryfikuj taśmę kamery w klapie ekranu. repair: • Zdejmij ramkę ekranu (bezel). • Odłącz taśmę kamery. • Wymień moduł kamery (zwykle klejony/zatrzaskiwany). • Podłącz, przetestuj obraz przed złożeniem. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-039','topic','','Wymiana głośników laptopa','','description: Wymiana przepalonych lub trzeszczących głośników laptopa. symptoms: • Brak dźwięku z głośników (słuchawki grają) • Trzaski, przester, zniekształcenia • Dźwięk tylko z jednego kanału diagnosis: • Sprawdź, czy problem znika po podłączeniu słuchawek (wtedy głośniki/wzmacniacz). • Test dźwięku lewy/prawy kanał. • Obejrzyj membrany głośników. repair: • Rozłóż spód laptopa. • Odkręć / odklej głośniki, odłącz złącze. • Zamontuj nowe głośniki, poprowadź kabel. • Przetestuj oba kanały. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-040','topic','','Naprawa mikrofonu','','description: Diagnoza i naprawa niedziałającego mikrofonu wbudowanego w laptopa. symptoms: • Mikrofon nie nagrywa / cichy • Szumy i przydźwięki • Nie wykrywany w systemie diagnosis: • Sprawdź ustawienia prywatności i poziom mikrofonu w Windows. • Test w Rejestratorze głosu. • Zweryfikuj taśmę mikrofonu (często przy kamerze). repair: • Zaktualizuj/przeinstaluj sterownik audio. • Sprawdź i wymień moduł mikrofonu (przy kamerze/zawiasie). • Przelutuj oderwany kabelek mikrofonu. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-041','topic','','Wymiana taśmy eDP/LVDS matrycy','','description: Naprawa migoczącego lub zanikającego obrazu spowodowanego uszkodzoną taśmą matrycy. symptoms: • Migotanie obrazu przy ruchu klapą • Pasy, przebarwienia, zanikanie obrazu • Obraz OK na HDMI, zły na matrycy diagnosis: • Podłącz monitor zewnętrzny (jeśli OK — wina matrycy/taśmy). • Poruszaj klapą — jeśli obraz reaguje, to taśma/przetarcie przy zawiasie. • Ustal typ złącza (30/40-pin eDP). repair: • Zdejmij ramkę, odłącz taśmę od matrycy i płyty. • Poprowadź nową taśmę przez zawias (bez naprężeń). • Podłącz, przyklej, przetestuj obraz w różnych kątach klapy. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-042','topic','','Wymiana obudowy / palmrest','','description: Wymiana pękniętej lub zniszczonej obudowy górnej (palmrest) i dolnej pokrywy. symptoms: • Pęknięta obudowa, ostre krawędzie • Wyłamane mocowania / luźne elementy • Zniszczony palmrest po zalaniu diagnosis: • Ustal model obudowy (P/N). • Oceń, które elementy przenieść (klawiatura, touchpad, głośniki). repair: • Rozłóż laptop do gołej płyty. • Przełóż podzespoły do nowej obudowy. • Poprowadź taśmy i anteny. • Skręć i sprawdź pasowanie oraz porty. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-043','topic','','Naprawa gniazda słuchawkowego (jack 3.5)','','description: Naprawa uszkodzonego lub zabrudzonego gniazda audio 3.5 mm. symptoms: • Brak dźwięku w słuchawkach / trzaski • System nie wykrywa słuchawek • Wtyk luźno trzyma w gnieździe diagnosis: • Wyczyść gniazdo (sprężone powietrze, IPA). • Sprawdź na innych słuchawkach. • Zweryfikuj przełącznik detekcji w gnieździe. repair: • Rozłóż laptop do gniazda audio. • Przelutuj / wymień gniazdo jack. • Sprawdź zimne luty w okolicy. • Przetestuj wykrywanie i dźwięk. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-044','topic','','Naprawa czytnika kart SD','','description: Diagnoza i naprawa niedziałającego czytnika kart pamięci SD/microSD. symptoms: • Karta SD nie wykrywana • Błędy odczytu / karta tylko do odczytu • Uszkodzone piny w slocie diagnosis: • Test na innej karcie i w innym czytniku. • Sprawdź sterownik czytnika (Realtek/O2Micro). • Obejrzyj piny slotu pod kątem wygięć. repair: • Zaktualizuj/przeinstaluj sterownik czytnika. • Wyprostuj lub wymień slot kart. • Przelutuj złącze slotu do płyty. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-045','topic','','Wymiana modułu WiFi/Bluetooth (M.2)','','description: Upgrade lub wymiana karty WiFi/BT w slocie M.2/E-key — szybszy internet i stabilny Bluetooth. symptoms: • Słaby zasięg / zrywanie WiFi • Brak Bluetooth • Karta WiFi znika z Menedżera urządzeń diagnosis: • Sprawdź, czy karta jest widoczna w systemie. • Zweryfikuj typ slotu (M.2 2230 E-key). • Sprawdź kompatybilność (whitelist BIOS w starszych laptopach). repair: • Rozłóż spód, odłącz anteny (delikatnie!). • Odkręć i wyjmij starą kartę. • Zamontuj nową (np. Intel AX210), podłącz anteny (1-Main, 2-Aux). • Zainstaluj sterowniki, przetestuj WiFi/BT. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-046','topic','','Naprawa podświetlenia klawiatury','','description: Naprawa niedziałającego podświetlenia klawiatury (LED, taśma, sterowanie Fn). symptoms: • Podświetlenie nie włącza się (Fn) • Świeci część klawiszy • Migotanie podświetlenia diagnosis: • Sprawdź skrót Fn i ustawienia producenta (np. Armoury/MyASUS). • Zweryfikuj, czy klawiatura ma w ogóle podświetlenie. • Sprawdź taśmę podświetlenia (osobna od klawiszy). repair: • Zaktualizuj oprogramowanie producenta / sterowniki. • Podłącz ponownie taśmę podświetlenia. • Wymień klawiaturę z podświetleniem, jeśli LED przepalone. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-047','topic','','Rozbudowa pamięci RAM','','description: Zwiększenie ilości RAM w laptopie/PC dla płynniejszej pracy i wielozadaniowości. symptoms: • Laptop zwalnia przy wielu kartach/programach • Pełne użycie RAM w Menedżerze zadań • Duże wykorzystanie pliku stronicowania diagnosis: • Sprawdź obecną RAM i wolne sloty (Menedżer zadań / CPU-Z). • Ustal typ (DDR4/DDR5), taktowanie i maks. pojemność płyty. • Sprawdź, czy RAM nie jest wlutowana (onboard). repair: • Dobierz kości zgodne (najlepiej parami — dual channel). • Zamontuj w slotach pod kątem, dociśnij do zatrzaśnięcia. • Ustaw XMP/EXPO w BIOS. • Przetestuj stabilność (MemTest86). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-048','topic','','Czyszczenie i konserwacja laptopa','','description: Okresowe czyszczenie z kurzu, wymiana pasty i konserwacja — dłuższa żywotność sprzętu. symptoms: • Głośna praca i wysoka temperatura • Zapchany kurzem wylot powietrza • Spadek wydajności (throttling) diagnosis: • Sprawdź temperatury i obroty wentylatorów. • Oceń zabrudzenie radiatora i kratek. repair: • Rozłóż spód, odkurz radiator i wentylator (sprężone powietrze, przytrzymaj łopatki). • Wymień pastę termoprzewodzącą i pady. • Przeczyść klawiaturę i obudowę. • Sprawdź temperatury po złożeniu. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron');
